-- Persistent, idempotent operational showcase data for a non-production demo environment.
-- This file intentionally creates non-login mock Auth rows and operational booking history.
-- It is NOT listed in supabase/config.toml and is never loaded by a normal local reset.
-- Apply only to an explicitly selected showcase environment after demo_catalogue.sql.
begin;

on conflict (id) do update set name=excluded.name, description=excluded.description, kind=excluded.kind, is_standalone_eligible=excluded.is_standalone_eligible, duration_minutes=excluded.duration_minutes, price_cents=excluded.price_cents, is_active=excluded.is_active, updated_at=now();

on conflict (id) do update set display_name=excluded.display_name, bio=excluded.bio, is_active=excluded.is_active, updated_at=now();

on conflict do nothing;

on conflict do nothing;

on conflict (id) do update set groomer_id=excluded.groomer_id, iso_day_of_week=excluded.iso_day_of_week, starts_at=excluded.starts_at, ends_at=excluded.ends_at, updated_at=now();

on conflict (id) do update set groomer_id=excluded.groomer_id, starts_at=excluded.starts_at, ends_at=excluded.ends_at, reason=excluded.reason, updated_at=now();

-- Mock customers are deliberately non-login Auth rows: no usable password or credential is stored.
on conflict (id) do update set email=excluded.email, raw_user_meta_data=excluded.raw_user_meta_data, updated_at=now();

on conflict (id) do update set role='CUSTOMER'::public.app_role, display_name=excluded.display_name, updated_at=now();

on conflict (id) do update set owner_id=excluded.owner_id, name=excluded.name, breed=excluded.breed, size=excluded.size, age_years=excluded.age_years, temperament=excluded.temperament, coat_condition=excluded.coat_condition, allergies=excluded.allergies, notes=excluded.notes, updated_at=excluded.updated_at;

on conflict (id) do update set customer_id=excluded.customer_id, pet_id=excluded.pet_id, groomer_id=excluded.groomer_id, status=excluded.status, starts_at=excluded.starts_at, service_ends_at=excluded.service_ends_at, blocked_until=excluded.blocked_until, subtotal_cents=excluded.subtotal_cents, applied_buffer_minutes=excluded.applied_buffer_minutes, cancelled_at=excluded.cancelled_at, completed_at=excluded.completed_at, created_at=excluded.created_at, updated_at=excluded.updated_at;

on conflict (appointment_id, service_id) do update set service_name=excluded.service_name, service_kind=excluded.service_kind, duration_minutes=excluded.duration_minutes, price_cents=excluded.price_cents, created_at=excluded.created_at;

update public.appointments appointment
set status_changed_at = coalesce(appointment.completed_at, appointment.cancelled_at, appointment.created_at), status_changed_by = null
where appointment.customer_id in (
  select profile.id from public.profiles profile join auth.users auth_user on auth_user.id=profile.id where auth_user.email like 'showcase.customer.%@example.invalid'
);

do $$
begin
  if (select count(*) from public.appointments appointment join auth.users auth_user on auth_user.id=appointment.customer_id where auth_user.email like 'showcase.customer.%@example.invalid') <> 493 then raise exception 'Unexpected mock appointment count'; end if;
  if (select count(*) from public.pets pet join auth.users auth_user on auth_user.id=pet.owner_id where auth_user.email like 'showcase.customer.%@example.invalid') <> 30 then raise exception 'Unexpected mock pet count'; end if;
  if exists (select 1 from public.appointments appointment where appointment.blocked_until <> appointment.service_ends_at + interval '15 minutes') then raise exception 'Invalid appointment cleanup buffer'; end if;
  if exists (select 1 from public.appointments appointment join (select appointment_id, sum(price_cents)::int subtotal from public.appointment_services group by appointment_id) snapshot on snapshot.appointment_id=appointment.id where appointment.customer_id in (select id from auth.users where email like 'showcase.customer.%@example.invalid') and appointment.subtotal_cents <> snapshot.subtotal) then raise exception 'Mock snapshot subtotal mismatch'; end if;
end;
$$;

commit;
